/* Additive integration; the detector remains at the URL provided by the owner. */
const SAFE_URL='https://guagua-cpu.github.io/smoke-recognition/web/index.html';
const SAFE_ORIGIN=new URL(SAFE_URL).origin;
const SAFE_ROLES=['inspector','company','admin'];
E.siteSafety||={channels:[],events:[]};
E.siteSafety.channels||=[];E.siteSafety.events||=[];
C.checklists['施工安全巡检']||=['核对视频位置和施工区域','由监理复核是否存在吸烟行为','记录责任人和现场处理措施','整改后复核并保留记录'];
let safetyTab='video';
const sb=(text,action,id='',primary=false)=>`<button class="${primary?'primary':'outline'} compact" data-safety="${action}" data-id="${esc(id)}">${text}</button>`;
const safetyEvents=()=>E.siteSafety.events.filter(x=>x.project===E.activeProject);
const safetyChannels=()=>E.siteSafety.channels.filter(x=>x.project===E.activeProject);
const safetyTime=n=>Math.floor((Number(n)||0)/60)+':'+String(Math.floor((Number(n)||0)%60)).padStart(2,'0');
if(!routes.some(r=>r[0]==='site-safety'))routes.push(['site-safety','现场安全监测']);
MODULES['site-safety']='现场安全监测';
for(const role of SAFE_ROLES){let group=NAVS[role].find(g=>g[1].includes('quality'))||NAVS[role][0];if(!group[1].includes('site-safety'))group[1].push('site-safety');}
const safePermitted=permitted;permitted=function(id){return id==='site-safety'?SAFE_ROLES.includes(state.role):safePermitted(id);};
function safetyEntry(){if(!SAFE_ROLES.includes(state.role)||!['home','quality','project'].includes(state.view)||$('#yunju-safety-card'))return;let card=document.createElement('section');card.id='yunju-safety-card';card.className='safety-entry';card.innerHTML=`<span class="safety-symbol">◉</span><div><span class="eyebrow">A SAFER PLACE TO BUILD</span><h2>看得见现场，也及时回应风险。</h2><p>吸烟自动识别与声光报警 · 上传视频测试 · 摄像头通道预留</p></div><div class="button-row">${sb('上传视频测试','open','',true)}${sb('摄像头通道','channels')}</div>`;$('#content').append(card);}
function renderSiteSafety(){let events=safetyEvents();return intro('CARE FOR THE PEOPLE WHO BUILD YOUR HOME','施工现场 · 视频识别与预警','先用施工视频测试吸烟识别，再逐步接入现场摄像头。当前启用范围：吸烟报警。',sb('质量巡检','quality')+sb('独立打开识别工具','external'))+`<div class="safety-metrics"><div><small>已启用识别</small><b>吸烟行为</b><span>检测窗口内自动报警</span></div><div><small>当前输入</small><b>上传视频测试</b><span>选择视频 → 开始识别 → 复核</span></div><div><small>摄像头通道</small><b>${safetyChannels().length} 个待接入</b><span>仅预留配置，不连接设备</span></div><div><small>本项目复核记录</small><b>${events.length} 条</b><span>${events.filter(e=>e.state!=='已闭环').length} 条待处理</span></div></div><div class="safety-tabs" role="tablist">${[['video','上传视频测试'],['channels','摄像头通道 · 待接入'],['events','事件复核与处理']].map(([id,label])=>`<button data-safety="tab" data-id="${id}" class="${id===safetyTab?'active':''}" role="tab" aria-selected="${id===safetyTab}">${label}</button>`).join('')}</div>`+(safetyTab==='channels'?safetyChannelView():safetyTab==='events'?safetyEventView():safetyVideoView());}
function safetyVideoView(){return `<section class="safety-workbench"><div class="safety-steps"><div><span>01</span><b>选择施工视频</b><p>在下方工具内上传视频，优先使用浏览器可播放的 MP4。</p></div><div><span>02</span><b>开始识别</b><p>首次会加载识别模型，等待工具内显示检测进度。</p></div><div><span>03</span><b>查看与复核报警</b><p>工具展示视频时间、截图与声音提示，由监理复核。</p></div></div><div class="safety-engine-heading"><div><h2>吸烟识别 · 上传视频测试</h2><p>检测及自动报警在下方工具内完成；当前不接通实时摄像头。</p></div><div class="button-row">${sb('刷新工具','reload')}${sb('放大窗口','fullscreen')}</div></div><div id="smoke-engine-host"></div><div class="safety-engine-footer"><span>模型与运行组件需联网加载；检测未开始或失败时，以工具内提示为准。</span><a href="${SAFE_URL}" target="_blank" rel="noopener noreferrer">独立窗口使用 ↗</a></div></section><section class="safety-coordination"><div><h3>从报警到处理，留下一份可追溯记录。</h3><p>自动识别与声光提示在检测窗口显示。云居事件簿保存监理复核后的记录，并可转为巡检整改任务。</p></div>${sb('登记复核事件','event-new','',true)}${sb('查看事件簿','events')}</section>`;}
function safetyChannelView(){return `<section class="camera-preparation"><div><span class="eyebrow">READY FOR THE NEXT CONNECTION</span><h2>为摄像头留好位置，让接入更从容。</h2><p>先登记通道名称、所在区域和计划传输方式。当前尚未绑定设备、拉取视频或启用实时识别。</p><div class="button-row">${sb('＋ 添加摄像头通道','channel-new','',true)}${sb('先用视频测试','video')}</div></div><div class="camera-placeholder"><span>▣</span><b>等待视频通道接入</b><small>设备绑定 · 流媒体网关 · 实时识别</small></div></section><div class="camera-grid">${safetyChannels().map(c=>`<article class="panel"><div class="summary-title"><h3>${esc(c.name)}</h3><span class="pill warm">待接入</span></div><p>${esc(c.area)} · ${esc(c.protocol)}</p><small>通道编号：${esc(c.device||'待绑定')}</small><div class="camera-placeholder small"><span>▣</span><small>尚无实时画面</small></div><div class="button-row">${sb('编辑配置','channel-edit',c.id)}${sb('移除通道','channel-remove',c.id)}</div></article>`).join('')||'<div class="safety-empty"><h3>还没有摄像头通道</h3><p>添加后保留为“待接入”，不会自动启动摄像头或生成报警。</p></div>'}</div><p class="component-note">RTSP 设备流需经流媒体网关转换后供浏览器播放。此版仅预留配置，不保存设备密码、不请求摄像头权限。</p>`;}
function safetyEventView(){let list=safetyEvents().slice().reverse();return `<section class="panel"><div class="section-head"><div><h2>吸烟事件 · 复核与处理</h2><p class="subtext">识别工具即时报警与云居复核记录分别标明来源。</p></div>${sb('＋ 登记复核事件','event-new','',true)}</div>${list.length?table(['事件 / 来源','视频与位置','区域 / 处理人','状态','操作'],list.map(e=>[esc(e.title)+'<small>'+esc(e.source)+'</small>',esc(e.video)+'<small>'+safetyTime(e.seconds)+'</small>',esc(e.area)+'<small>'+esc(e.assignee)+'</small>',badge(e.state),sb('详情与复核','event-view',e.id)+(e.check?go('查看关联巡检','quality'):sb('转为巡检整改','event-to-check',e.id))])):'<div class="safety-empty"><span>✓</span><h3>当前没有已登记的复核事件</h3><p>先在识别工具查看检测结果，再登记需要跟进的事件；此处不预置模拟报警。</p></div>'}</section><div class="notice">当前自动报警由嵌入工具展示，未自动回传到云居。摄像头和报警回传接口均已预留；事件经监理复核后组织处理。</div>`;}
newViews['site-safety']=renderSiteSafety;
function mountSmokeEngine(){let host=$('#smoke-engine-host');if(!host)return;let shell=$('#yunju-smoke-engine');if(!shell){shell=document.createElement('div');shell.id='yunju-smoke-engine';shell.className='smoke-engine';shell.innerHTML=`<div class="engine-message" role="status">正在载入识别网页…</div><iframe id="yunju-smoke-frame" title="施工视频吸烟识别与自动报警：上传视频测试" src="${SAFE_URL}" allow="autoplay; fullscreen" referrerpolicy="strict-origin-when-cross-origin"></iframe>`;shell.querySelector('iframe').addEventListener('load',()=>{shell.querySelector('.engine-message').textContent='识别网页已载入 · 请在工具内选择视频并开始';});}if(shell.dataset.project&&shell.dataset.project!==E.activeProject)shell.querySelector('iframe').src=SAFE_URL;shell.dataset.project=E.activeProject;host.append(shell);shell.hidden=false;}
const beforeSafetyRender=render;render=function(){let shell=$('#yunju-smoke-engine');if(shell){shell.hidden=true;document.body.append(shell);}beforeSafetyRender();safetyEntry();if(state.view==='site-safety'&&safetyTab==='video')mountSmokeEngine();};
function safetyNewEvent(data,source='监理登记 · 待复核'){let e={id:uid('safety'),project:E.activeProject,title:'吸烟行为待复核',video:String(data.video||'待补视频名称').slice(0,180),seconds:Math.max(0,Number(data.seconds)||0),area:String(data.area||'待核实').slice(0,120),assignee:String(data.assignee||currentProject().main).slice(0,160),note:String(data.note||'').slice(0,3000),state:'待复核',source,time:new Date().toISOString(),history:[],check:''};E.siteSafety.events.push(e);audit('登记吸烟复核事件',e.video+' · '+safetyTime(e.seconds));persist();return e;}
function safetyEventForm(){openForm('登记视频中的吸烟复核事件',[field('video','原视频名称'),field('seconds','视频位置 / 秒','number',[],{min:0}),field('area','房间或施工区域'),field('assignee','处理负责人'),field('note','识别现象、复核依据和处理安排','textarea',[],{wide:true})],{seconds:0,area:'公共作业区',assignee:currentProject().main},d=>{safetyNewEvent(d);},'本记录由监理主动登记；自动报警在识别工具内显示。');}
function safetyChannelForm(id){let c=E.siteSafety.channels.find(c=>c.id===id);openForm(c?'编辑摄像头通道':'预留摄像头视频通道',[field('name','通道名称'),field('area','施工区域'),field('protocol','计划接入方式','select',['HLS','WebRTC','RTSP（需流媒体网关）','由设备服务商确认']),field('device','设备 / 通道编号','text',[],{required:false})],c||{name:'施工现场通道',area:'公共作业区',protocol:'由设备服务商确认'},d=>{if(c)Object.assign(c,d);else E.siteSafety.channels.push({id:uid('camera'),project:E.activeProject,...d,state:'待接入'});audit('摄像头通道配置',d.name+' · 待接入');},'仅保存通道占位配置，当前不连接设备、不启用摄像头或实时报警。');}
function safetyEventDetail(id){let e=E.siteSafety.events.find(e=>e.id===id);if(!e)return;modal('吸烟事件 · 复核记录',detailCells({'来源':e.source,'视频':e.video,'时间位置':safetyTime(e.seconds),'施工区域':e.area,'处理负责人':e.assignee,'状态':e.state,'记录日期':new Date(e.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})})+`<p class="safety-note">${esc(e.note)}</p><div class="button-row">${sb('记录复核结果','event-review',e.id)}${e.check?go('查看关联巡检','quality'):sb('转为巡检整改','event-to-check',e.id)}</div>${e.history.map(h=>`<p class="subtext">${esc(h.time.slice(0,16))} · ${esc(h.result)} · ${esc(h.note)}</p>`).join('')}`,true);}
const SAFETY_ACTIONS={
 open:()=>{safetyTab='video';route('site-safety');},channels:()=>{safetyTab='channels';route('site-safety');},video:()=>{safetyTab='video';render();},events:()=>{safetyTab='events';render();},tab:el=>{safetyTab=el.dataset.id;render();},quality:()=>route('quality'),external:()=>window.open(SAFE_URL,'_blank','noopener,noreferrer'),
 reload:()=>{let f=$('#yunju-smoke-frame');if(f)f.src=SAFE_URL;},fullscreen:()=>$('#yunju-smoke-frame')?.requestFullscreen?.().catch(()=>toast('可在独立窗口打开完整识别工具')),
 'channel-new':()=>safetyChannelForm(),'channel-edit':el=>safetyChannelForm(el.dataset.id),'channel-remove':el=>{E.siteSafety.channels=E.siteSafety.channels.filter(c=>c.id!==el.dataset.id);audit('移除待接入通道',el.dataset.id);commit('通道已移除');},'event-new':()=>safetyEventForm(),'event-view':el=>safetyEventDetail(el.dataset.id),
 'event-review':el=>{let e=E.siteSafety.events.find(e=>e.id===el.dataset.id);if(!e)return;openForm('记录事件复核与处理',[field('result','处理状态','select',['待复核','已确认 · 待处理','误报 / 无法确认','已闭环']),field('note','复核依据、措施与结果','textarea',[],{wide:true})],{result:e.state},d=>{e.state=d.result;e.history.push({...d,time:new Date().toISOString()});audit('安全事件复核',e.id+' · '+d.result);});},
 'event-to-check':el=>{let e=E.siteSafety.events.find(e=>e.id===el.dataset.id);if(!e||e.check)return;C.checklists['施工安全巡检']||=['核对视频位置和施工区域','由监理复核是否存在吸烟行为','记录责任人和现场处理措施','整改后复核并保留记录'];let id=uid('check');E.checks.push({id,project:E.activeProject,stage:'施工安全巡检',room:e.area,state:'待检查',date:new Date(Date.now()+8*3600000).toISOString().slice(0,10),values:{},evidence:[],issues:['吸烟事件待复核：'+e.video+' · '+safetyTime(e.seconds)],report:false});e.check=id;notify('现场安全事件需复核：'+e.area,['inspector','builder','company'],'quality');audit('安全事件转巡检',e.id+' → '+id);commit('已关联巡检任务，并生成本地项目提醒');}
};
document.addEventListener('click',e=>{let el=e.target.closest('[data-safety]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();if(!SAFE_ROLES.includes(state.role))return toast('请切换到监理、企业或平台工作台');SAFETY_ACTIONS[el.dataset.safety]?.(el);},true);
// Reserved protocol, not emitted by the current external page. Validate both
// sender frame and origin and accept smoking events only.
window.addEventListener('message',e=>{let f=$('#yunju-smoke-frame'),d=e.data;if(!f||e.source!==f.contentWindow||e.origin!==SAFE_ORIGIN||!d||d.type!=='yunju:smoking-alarm'||d.kind!=='smoking'||!SAFE_ROLES.includes(state.role))return;let key=String(d.id||'').slice(0,160);if(key&&E.siteSafety.events.some(x=>x.externalId===key))return;let item=safetyNewEvent({video:d.video,seconds:d.time,area:d.area,note:'识别工具通过约定接口回传，待监理复核'},'识别工具回传 · 待复核');item.externalId=key;persist();if(state.view==='site-safety'&&safetyTab==='events')render();});

/* Same-origin shortcuts invoke BoHack's own tools and save/undo behavior. */
function addMepGuide(){let p=$('#space-page');if(!p||p.hidden||$('#yunju-mep-guide',p))return;let box=document.createElement('section');box.id='yunju-mep-guide';box.className='mep-guide';box.innerHTML=`<div><span class="eyebrow">EVERY HIDDEN CONNECTION, MADE VISIBLE</span><h3>水电管线，让看不见的细节也清楚。</h3><p>强弱电、冷热水、暖气和空调示意；二维编辑、三维同步，保留家具布置与漫游。</p></div><div class="button-row"><button class="outline compact" data-mep="layers">打开管线图层</button><button class="outline compact" data-mep="auto">自动生成管线</button><button class="outline compact" data-mep="draw">绘制管线</button><button class="outline compact" data-mep="node">放置节点</button><button class="primary compact" data-mep="three">三维查看管线</button></div><small>在工具中点击“自动管线”生成初稿，再逐点编辑。当前为工程示意，正式施工前需专业核对。</small>`;p.querySelector('.studio-layout')?.before(box);}
const beforeMepSpace=renderSpace;renderSpace=function(){beforeMepSpace();addMepGuide();};
document.addEventListener('click',e=>{let b=e.target.closest('[data-mep]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();let doc=$('#space-page iframe')?.contentDocument;if(!doc)return toast('三维工具正在载入，请稍后操作');if(b.dataset.mep==='three'){openMepThreeWhenReady(doc);return;}doc.querySelector('[data-view="2d"]')?.click();for(const type of ['elec','water']){let chip=doc.querySelector(`[data-layer="${type}"]`);if(chip&&!chip.classList.contains('on'))chip.click();}if(b.dataset.mep==='auto')doc.querySelector('#mepAuto')?.click();if(b.dataset.mep==='draw')doc.querySelector('[data-tool="mepLine"]')?.click();if(b.dataset.mep==='node')doc.querySelector('[data-tool="mepNode"]')?.click();},true);
persist();if(location.hash==='#site-safety'&&SAFE_ROLES.includes(state.role))state.view='site-safety';render();

function openMepThreeWhenReady(doc){
 const win=doc.defaultView;
 const enter=()=>{doc.querySelector('[data-view="3d"]')?.click();for(const type of ['elec','water']){let chip=doc.querySelector(`[data-t="${type}"]`);if(chip&&!chip.classList.contains('on'))chip.click();}};
 if(win?.View3D){enter();return;}
 toast('三维引擎正在加载，就绪后将自动打开');let attempts=0;
 const pending=setInterval(()=>{attempts++;if(win?.View3D){clearInterval(pending);enter();}else if(attempts>=60){clearInterval(pending);toast('三维引擎暂未加载完成，请稍后重试或独立打开工具');}},500);
}
